INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes, positive_marks, negative_marks)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07c936cf-d0d0-4973-b3fb-21b02acefa9c', '2da59c0c-b5c3-4268-b279-13d98fc5a36b', 0, 'ReadWriteOnce');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48a95bb7-aa53-4ee5-a98c-9ccb0333a508', '2da59c0c-b5c3-4268-b279-13d98fc5a36b', 1, 'ReadOnlyMany');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('539e9f08-36a9-493c-b2b2-d51bf97e3157', '2da59c0c-b5c3-4268-b279-13d98fc5a36b', 2, 'ReadWriteMany');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d1a8125-fe9d-408d-b9d7-287f0855541e', '2da59c0c-b5c3-4268-b279-13d98fc5a36b', 3, 'ReadWriteOncePod');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5864a0f7-1e39-4ea1-8f4e-2ba2a17a09ba', '6213fd28-4b9d-4718-aceb-594532f843c4', 0, 'ReadWriteOncePod restricts the volume to a single Pod cluster-wide, whereas ReadWriteOnce restricts it to a single node (multiple Pods on that node can still mount it)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b592146f-3606-44ac-ae2f-49ea2ad71386', '6213fd28-4b9d-4718-aceb-594532f843c4', 1, 'ReadWriteOncePod allows multiple nodes, ReadWriteOnce allows only one');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a921336d-3016-4735-8812-43f19d3fffd5', '6213fd28-4b9d-4718-aceb-594532f843c4', 2, 'They are functionally identical; ReadWriteOncePod is just a newer alias for ReadWriteOnce');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c9653f57-0311-4ad5-af6f-ef02851e6b18', '6213fd28-4b9d-4718-aceb-594532f843c4', 3, 'ReadWriteOncePod only applies to Block volumes, ReadWriteOnce only to Filesystem volumes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59f47acf-9214-4222-a704-e6b9b390d312', '5f79f8a8-856c-465b-9d97-662c6cf868eb', 0, 'The volume is presented to the container as a raw block device with no filesystem, and the application must manage it directly');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5497e4a-b00e-4f1e-bdf5-d44c40f27207', '5f79f8a8-856c-465b-9d97-662c6cf868eb', 1, 'The volume is automatically formatted with ext4 before mounting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('29afb82c-1495-4a42-963f-c74eb4672e9c', '5f79f8a8-856c-465b-9d97-662c6cf868eb', 2, 'The volume can no longer be dynamically provisioned');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f094b97d-17e3-4f0b-8ea9-9300b8741349', '5f79f8a8-856c-465b-9d97-662c6cf868eb', 3, 'The volume becomes read-only');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62091e91-c9bb-4c45-9d0a-27704a7d255f', '453fb7fa-e399-4c68-94dd-1f2731cce922', 0, 'capacity, accessModes, and a volume source (e.g. hostPath, nfs, or a CSI block) — the PVC is created separately to bind to it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('31e3d79a-527b-4939-b1fd-efc5a3da2939', '453fb7fa-e399-4c68-94dd-1f2731cce922', 1, 'Only a StorageClass name; capacity is inferred from the PVC automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2e4436f-d319-4ff8-a9be-11c2488ecfda', '453fb7fa-e399-4c68-94dd-1f2731cce922', 2, 'Only accessModes; capacity is optional for statically provisioned volumes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b5ffd59-7021-4ecb-aa65-173a2299d57b', '453fb7fa-e399-4c68-94dd-1f2731cce922', 3, 'None — static provisioning requires a CSI driver and cannot be done manually');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7bd6c89a-70b7-4912-a580-7ddbf38d2c5f', 'ab3f3b9e-fd9a-415a-bdf2-dcdbf7587687', 0, 'Retain');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('acd5d835-8841-48fa-b067-ee59f5936925', 'ab3f3b9e-fd9a-415a-bdf2-dcdbf7587687', 1, 'Delete');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13eb0264-ccfe-4f5f-a40f-ba063e29f79d', 'ab3f3b9e-fd9a-415a-bdf2-dcdbf7587687', 2, 'Recycle');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e93dca1-a23a-4d42-b910-ea7ee84d4dc3', 'ab3f3b9e-fd9a-415a-bdf2-dcdbf7587687', 3, 'Immediate');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ddac0d5-fbeb-4826-9333-4e12782956e6', 'baed106a-9d6e-42f2-a44a-c6d33b2200ec', 0, 'The PV is automatically deleted along with its underlying storage');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b9f447b-9c26-4d89-a99e-69ff27bea298', 'baed106a-9d6e-42f2-a44a-c6d33b2200ec', 1, 'The PV moves to the Released phase; its data and underlying storage are preserved, but it isn''t automatically available for a new claim until manually reclaimed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a51624a4-5785-479b-98c0-5b279c12c71e', 'baed106a-9d6e-42f2-a44a-c6d33b2200ec', 2, 'The PV is automatically recycled by wiping its data and returning to Available');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2eaa8555-ade0-4d46-9874-5347c46cfdea', 'baed106a-9d6e-42f2-a44a-c6d33b2200ec', 3, 'The PV remains Bound indefinitely, even with no matching PVC');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53e60233-2dc8-4fd7-9faf-557bd7b8222b', '2e89e09b-27db-43e1-840f-f98acad60f48', 0, 'Nothing — Kubernetes automatically rebinds Released PVs to the next matching PVC');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14e978f3-970d-400d-8a84-fd58d5e62637', '2e89e09b-27db-43e1-840f-f98acad60f48', 1, 'Manually clear the PV''s spec.claimRef field (and typically also confirm/clean the underlying data) before it can be bound again');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c6a7a9e-616d-4245-bd6c-9749c9178fbc', '2e89e09b-27db-43e1-840f-f98acad60f48', 2, 'Delete and recreate the StorageClass');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f3ef559-a1df-4c34-9323-1950370dd662', '2e89e09b-27db-43e1-840f-f98acad60f48', 3, 'Set the PV''s accessModes to ReadWriteMany');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a44b41d-bcd3-47a8-a065-4d775399bfe1', 'cad347bc-9025-4aad-ba78-e4b1e518491b', 0, 'The PV''s capacity must be >= the PVC''s request, its accessModes must include what the PVC requests, and its storageClassName must match (an empty PVC class matches only classless PVs, unless a default class applies)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('828b7568-b1c7-4cc5-94bf-ca00068d6b88', 'cad347bc-9025-4aad-ba78-e4b1e518491b', 1, 'Only that the PV and PVC share the same name');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5d10a24-ba04-473d-bdcd-98099cd987da', 'cad347bc-9025-4aad-ba78-e4b1e518491b', 2, 'Only that the PV''s capacity exactly equals the PVC''s request, down to the byte');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('657f3b04-8de9-4073-a1a1-f7d5b255b897', 'cad347bc-9025-4aad-ba78-e4b1e518491b', 3, 'PVCs cannot bind to pre-existing PVs at all — only to dynamically provisioned ones');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fbd1ab8f-6a88-495f-9c75-421031d881d2', '1831ac6e-34ec-418b-8560-70e0249a92db', 0, 'The underlying PV uses an access mode like ReadWriteOnce, and a Pod using the same PVC is still (or was recently) attached on a different node — common during a reschedule');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('10da140f-6bbd-4063-a962-8e1340424e71', '1831ac6e-34ec-418b-8560-70e0249a92db', 1, 'The StorageClass has allowVolumeExpansion set to false');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be198977-ce78-40eb-ab5d-af2f9af788eb', '1831ac6e-34ec-418b-8560-70e0249a92db', 2, 'The Pod''s securityContext.runAsNonRoot is set to true');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fdbe3107-4929-4735-a516-4b3976cb4a18', '1831ac6e-34ec-418b-8560-70e0249a92db', 3, 'The NetworkPolicy for the namespace is blocking the CSI driver''s traffic');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9316addb-fce5-4b3e-8060-176815e10222', 'af203aa1-f93a-44ca-bdb8-9659162bdf9b', 0, 'Mount only a specific file or subdirectory from within the referenced volume, rather than the volume''s entire root');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6453cedb-8c68-4d14-ab90-bfd092ec3e3f', 'af203aa1-f93a-44ca-bdb8-9659162bdf9b', 1, 'Mount the same volume as read-only automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ace9c0d4-d4f3-496c-9f86-f4b07879a1c3', 'af203aa1-f93a-44ca-bdb8-9659162bdf9b', 2, 'Split a single PVC into multiple independent PVs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ede9cd6-c968-4298-8968-dd195687db38', 'af203aa1-f93a-44ca-bdb8-9659162bdf9b', 3, 'Bypass the access mode restrictions of the underlying PV');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f115ff5-66db-45a9-8684-ae6f3f59463b', 'c5aa295d-9275-4a9f-afbf-2dda739a09b8', 0, 'It''s backed by a PersistentVolumeClaim that''s automatically created and tied to the Pod''s lifecycle, so it can use any CSI storage driver/StorageClass — unlike emptyDir, which is always local node storage');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('967e319d-cdd0-41ae-b520-1671c2add082', 'c5aa295d-9275-4a9f-afbf-2dda739a09b8', 1, 'It''s identical to emptyDir but with a different name in the API');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e37aca74-9ed2-43af-a458-1b781239a73c', 'c5aa295d-9275-4a9f-afbf-2dda739a09b8', 2, 'It can only be used with StatefulSets, never with Deployments');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c296bebd-148e-4e4f-89fd-498cbdfbc67a', 'c5aa295d-9275-4a9f-afbf-2dda739a09b8', 3, 'It persists even after the Pod is permanently deleted, unlike a PVC-backed volume');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b9c5060f-a04d-41b7-a2e7-ad3d8863970a', '5e199b75-3897-4996-9b11-df4b517d8499', 0, 'The PVCs are deleted immediately along with the terminated Pods');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5f34c53-9c37-4fb1-8e0f-9d77c0eb3090', '5e199b75-3897-4996-9b11-df4b517d8499', 1, 'The PVCs are retained by default, so scaling back up reattaches the same PVC (and its data) to the recreated ordinal Pod');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0a9395b-6a62-44a1-a746-800dc1dcb2b8', '5e199b75-3897-4996-9b11-df4b517d8499', 2, 'The PVCs are automatically converted to a different StorageClass');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cfeb03cc-b52a-4143-b386-386b14868189', '5e199b75-3897-4996-9b11-df4b517d8499', 3, 'The PVCs become read-only until manually released');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('594cd900-ac42-4b82-8a7a-a19fb902bb4d', '8e8cd8ee-8339-4094-8daf-4177ec8c7d9e', 0, 'storage.k8s.io/v1');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4caa9121-6b01-4c40-b058-a9c29aeb2f44', '8e8cd8ee-8339-4094-8daf-4177ec8c7d9e', 1, 'apps/v1');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84dc275a-aefd-4192-86ee-9e04f7a9ccad', '8e8cd8ee-8339-4094-8daf-4177ec8c7d9e', 2, 'core/v1 (no group)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('06693cbc-99a5-45e8-a1a4-47655bc505d9', '8e8cd8ee-8339-4094-8daf-4177ec8c7d9e', 3, 'scheduling.k8s.io/v1');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1405c954-7ddf-454c-93ba-a31195ca096e', '49e94614-1da1-43d9-9479-3d9f43c253cc', 0, 'PV provisioning/binding is delayed until a Pod using the PVC is actually scheduled, so the volume can be created in the same zone/node topology as that Pod');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eabb1443-de10-4690-b43e-ce64471ab2c3', '49e94614-1da1-43d9-9479-3d9f43c253cc', 1, 'The PVC will never be bound to any PV');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86a5df5a-2c9b-424a-be42-e4c8c3851c03', '49e94614-1da1-43d9-9479-3d9f43c253cc', 2, 'Provisioning happens immediately, but the Pod is never scheduled until the PVC is bound');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('58f468a7-3d7e-4362-b85f-f5af57447c50', '49e94614-1da1-43d9-9479-3d9f43c253cc', 3, 'It disables dynamic provisioning entirely, forcing static provisioning');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2e177ee-20e8-420a-9ca2-839c82bffebb', 'b5623599-fb81-4428-a4ae-0e9e9ad3c73e', 0, 'The expansion request is rejected/has no effect — allowVolumeExpansion must be true on the StorageClass for a PVC using it to be resized');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75efb8a2-8b36-4a7f-9370-880db5e0f655', 'b5623599-fb81-4428-a4ae-0e9e9ad3c73e', 1, 'The PVC shrinks instead of growing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af2c5e48-0aea-4549-ac0b-9d31dd9af454', 'b5623599-fb81-4428-a4ae-0e9e9ad3c73e', 2, 'The PV is deleted and recreated automatically at the new size');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dad0aa72-f892-49ba-b106-b4f12ccbb917', 'b5623599-fb81-4428-a4ae-0e9e9ad3c73e', 3, 'The change succeeds regardless, since allowVolumeExpansion only affects reclaim behavior');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fbe0966f-9da6-400e-b1ff-6ae1e18b3678', '6c2d8bd9-966c-4f87-87c7-f06e53a5789c', 0, 'Only growing the volume to a larger size — shrinking a PVC''s storage request is not supported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc26e25e-2798-475e-9425-ce729b3c628f', '6c2d8bd9-966c-4f87-87c7-f06e53a5789c', 1, 'Only shrinking, never growing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f596b428-fed7-40ad-a246-5913260bb074', '6c2d8bd9-966c-4f87-87c7-f06e53a5789c', 2, 'Both growing and shrinking are fully supported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('58e1463e-fa8f-46d3-9c08-6f93ea99be9c', '6c2d8bd9-966c-4f87-87c7-f06e53a5789c', 3, 'Neither — a new PVC must always be created');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1c5e44a-3901-48fc-b122-7179ba5bfcf5', '43cecb6c-2d86-4032-9c77-f3d519ef08a2', 0, 'The PVC stays Pending forever, since storageClassName is mandatory');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8e370ba1-d4a4-48ce-9ab8-830c5aed0472', '43cecb6c-2d86-4032-9c77-f3d519ef08a2', 1, 'The PVC is automatically assigned that default StorageClass, and dynamic provisioning proceeds via its provisioner');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('72f4a328-c284-4f65-ba0b-6781bcd67096', '43cecb6c-2d86-4032-9c77-f3d519ef08a2', 2, 'The PVC binds only to statically-provisioned PVs with no class at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1f2638fc-8049-4048-8196-4deb3b697867', '43cecb6c-2d86-4032-9c77-f3d519ef08a2', 3, 'Kubernetes rejects the PVC at admission');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d3814ea-f18f-4d09-b723-c5cd106fc5f4', 'caf61d46-d173-4024-85f0-6c6ca11b4a6a', 0, 'It''s treated the same as explicitly setting storageClassName: '''' and will only bind to a pre-existing PV that also has no storage class — otherwise it stays Pending');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d1f8f1d6-0e58-447f-8083-4ba6ad2333ae', 'caf61d46-d173-4024-85f0-6c6ca11b4a6a', 1, 'It automatically picks whichever StorageClass was created first');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a83f873e-c811-4298-b6a8-cf92d18c1459', 'caf61d46-d173-4024-85f0-6c6ca11b4a6a', 2, 'It fails validation and cannot be created');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e4dd4a27-22df-4695-b5fc-264da741f3a6', 'caf61d46-d173-4024-85f0-6c6ca11b4a6a', 3, 'It provisions using the CSI driver with the fewest existing volumes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('481aa777-abf3-4cc5-89ab-604afee251a0', 'e12e23c0-337f-4c85-b023-d41a30079a11', 0, 'The volume plugin (in-tree name or, more commonly today, a CSI driver name) responsible for actually creating the underlying storage on demand');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('265acf43-96fe-41e8-9a31-11bf8aee7f8f', 'e12e23c0-337f-4c85-b023-d41a30079a11', 1, 'The Kubernetes node designated to host all PVs from this class');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e435e090-1882-4f6f-af1d-62f28329e3a9', 'e12e23c0-337f-4c85-b023-d41a30079a11', 2, 'The maximum number of PVCs allowed to use this class');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8928d7e3-c1ec-43a1-af71-5b747ec311d5', 'e12e23c0-337f-4c85-b023-d41a30079a11', 3, 'The RBAC role permitted to create PVCs against this class');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c59cc640-a85d-46ad-be84-e339f119c746', '461680b6-55b8-409a-9ffa-0f92248a0e4f', 0, 'It implements a standardized plugin interface so storage vendors can provide provisioning/attaching/mounting logic without that code living in Kubernetes core (replacing older in-tree volume plugins)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('916c237e-29fc-49ac-8e5c-070f59a14dac', '461680b6-55b8-409a-9ffa-0f92248a0e4f', 1, 'It replaces kube-proxy for storage-related networking');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('04e5d1a8-1a87-4a70-8adc-1f4ce41d5d8a', '461680b6-55b8-409a-9ffa-0f92248a0e4f', 2, 'It''s only used for logging PV events, with actual provisioning still handled in-tree');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15bea015-1991-4984-bbaa-031976c26633', '461680b6-55b8-409a-9ffa-0f92248a0e4f', 3, 'It''s required only for emptyDir and hostPath volumes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a949fc7-bdc4-43d5-9f3a-36c14d9783f7', 'cfdafee9-c0c9-48a5-a4d6-ee6c8ab32b36', 0, 'accessModes and volumeMode — the requested storage size can be increased if the StorageClass allows expansion, but access mode/volume mode cannot be changed after the fact');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6fb51030-6d45-4ab8-8953-b6dfd9c38df5', 'cfdafee9-c0c9-48a5-a4d6-ee6c8ab32b36', 1, 'resources.requests.storage, which can never be changed under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20b01c81-b197-45fc-833b-60fd6136aafb', 'cfdafee9-c0c9-48a5-a4d6-ee6c8ab32b36', 2, 'storageClassName, which can always be freely changed after binding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2530d8c9-5756-4a31-be2f-49412a35ee6a', 'cfdafee9-c0c9-48a5-a4d6-ee6c8ab32b36', 3, 'None of the PVC spec fields are immutable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4456af3f-9c9f-48be-9777-6e18ce613b72', '368d5346-3d58-4e5a-9b3a-ec8fe55ab851', 0, 'A nodeAffinity rule on the PV itself, since local storage isn''t network-attached and can''t just be mounted from any node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('508f7b86-1cc6-45a4-89e2-4396721ab8fd', '368d5346-3d58-4e5a-9b3a-ec8fe55ab851', 1, 'A NetworkPolicy restricting traffic to that node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77d856d2-0a57-4d07-94a8-13fe4c19204a', '368d5346-3d58-4e5a-9b3a-ec8fe55ab851', 2, 'Nothing extra — local PVs are automatically node-agnostic');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('58cdd38d-81ad-4b02-b4ab-576cc59cf020', '368d5346-3d58-4e5a-9b3a-ec8fe55ab851', 3, 'A DaemonSet must be deployed to replicate the data to every node');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1bf679d2-c109-4b7f-8a7f-74b4b443e24c', 'ca6917bb-73d8-4e42-9e30-e52c98bea1c0', 0, 'kubectl describe pvc <name> — its Events typically show the exact reason (no matching PV, no default StorageClass, provisioner failure, etc.)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b4d501f-bb18-4db2-8831-237bfa97e887', 'ca6917bb-73d8-4e42-9e30-e52c98bea1c0', 1, 'kubectl logs <pvc-name>');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b62b0f71-5bc7-40d3-ac70-4528127a24ff', 'ca6917bb-73d8-4e42-9e30-e52c98bea1c0', 2, 'kubectl rollout status pvc/<name>');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4661532c-2db5-42d1-9fa2-1ccf11a36354', 'ca6917bb-73d8-4e42-9e30-e52c98bea1c0', 3, 'kubectl top pvc <name>');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('181170d4-47c7-48c6-a2a0-26f00756dcc9', '430f971e-e2f3-4b22-b064-0f1556bf7ee3', 0, 'The container exceeded its memory limit (or the node ran out of available memory) and the kernel''s OOM killer terminated its process');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('989033e7-72c1-48b3-9cb7-87b8bad38df5', '430f971e-e2f3-4b22-b064-0f1556bf7ee3', 1, 'The container was killed because its livenessProbe failed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8879f2fe-1208-40a6-81b9-e2f91aa451b9', '430f971e-e2f3-4b22-b064-0f1556bf7ee3', 2, 'The container exceeded its CPU limit and was throttled');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cbe7f26f-0942-4429-853d-40629f25bad3', '430f971e-e2f3-4b22-b064-0f1556bf7ee3', 3, 'The container failed to pull its image within a timeout');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac95e33b-da3d-4d4a-9e8e-b08fe1673e50', 'a37b876f-dd40-4a12-a1b1-d8b32ec1df10', 0, 'BestEffort Pods (no requests/limits set) first, then Burstable Pods exceeding their requests, with Guaranteed Pods evicted last');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf91b6cd-6e12-48a4-b007-7952ec039480', 'a37b876f-dd40-4a12-a1b1-d8b32ec1df10', 1, 'Guaranteed QoS Pods first, to protect BestEffort workloads');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12a98fd4-6dcb-46e7-9101-11ce0596f3d8', 'a37b876f-dd40-4a12-a1b1-d8b32ec1df10', 2, 'Whichever Pod has been running longest, regardless of QoS class');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('453635fb-2f66-4c38-b2a7-c26c349b01ea', 'a37b876f-dd40-4a12-a1b1-d8b32ec1df10', 3, 'Only Pods in the kube-system namespace');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('968e2d42-946d-42bb-a0d4-3c993478da47', '0fd2ff6c-1906-4304-aaca-b3b7e7e92dd0', 0, 'No node currently has enough allocatable CPU left to satisfy the Pod''s CPU requests, given what''s already requested by other Pods on each node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9a1c1b0-19e8-4527-86e5-4fe1cf8c4d0b', '0fd2ff6c-1906-4304-aaca-b3b7e7e92dd0', 1, 'The Pod''s image failed to pull on all 3 nodes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2f4e8342-12c6-4e37-b062-5303ab73fd19', '0fd2ff6c-1906-4304-aaca-b3b7e7e92dd0', 2, 'The cluster''s CPU manager policy is set to ''none''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14c5dbc4-3f1c-4d75-a545-3066a9aa93b1', '0fd2ff6c-1906-4304-aaca-b3b7e7e92dd0', 3, 'A NetworkPolicy is blocking the scheduler from reaching any node');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9b862927-6bdf-4aba-83b7-55f5b3ca2a58', '52fe7abe-1c8c-4512-974e-6061adf7b869', 0, 'The Pod remains Pending indefinitely with a FailedScheduling event, since a ''required'' rule is a hard constraint');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('49aa8731-f73c-491d-9082-27e3c2634c0f', '52fe7abe-1c8c-4512-974e-6061adf7b869', 1, 'The scheduler ignores the rule after 30 seconds and schedules it anyway');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3de896d0-b694-4297-ade0-3464ac1b1003', '52fe7abe-1c8c-4512-974e-6061adf7b869', 2, 'The Pod is scheduled to a random node and the label is applied automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01e75b99-c635-4a42-b323-faeea32eb2d8', '52fe7abe-1c8c-4512-974e-6061adf7b869', 3, 'The API server rejects the Pod at admission time');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21d6a766-f694-456f-871f-d9f35148a93b', 'b777c514-e5e2-4cd0-bf8f-437bb089bc96', 0, 'The scheduler will not place the Pod on that node at all, though already-running Pods on it (scheduled before the taint) are unaffected by NoSchedule specifically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c75e718a-a801-4e2c-bbd3-107f14474ac7', 'b777c514-e5e2-4cd0-bf8f-437bb089bc96', 1, 'The Pod is scheduled there anyway but immediately evicted');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e601b59-f11e-4c20-afbe-2609b939d7f2', 'b777c514-e5e2-4cd0-bf8f-437bb089bc96', 2, 'The taint only affects Services, not Pod scheduling');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3dd31a31-ee0b-4197-a8ca-ee6881061db2', 'b777c514-e5e2-4cd0-bf8f-437bb089bc96', 3, 'The Pod is scheduled there with a warning event but otherwise runs normally');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af9ca49b-eb12-45e8-bdef-4ea899607f6c', '7b70aa86-595d-4e94-9a9c-d4abb7717ae8', 0, 'A typo in the image name or tag');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc3a7e98-c39f-4b2d-9572-92b65525c832', '7b70aa86-595d-4e94-9a9c-d4abb7717ae8', 1, 'Missing imagePullSecrets for a private registry');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd6d0a9b-71a4-453a-b2cb-b76b8698298d', '7b70aa86-595d-4e94-9a9c-d4abb7717ae8', 2, 'Registry rate-limiting, or the registry being unreachable from the node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2aad667c-1d89-439d-9e8c-a7ef95bafe04', '7b70aa86-595d-4e94-9a9c-d4abb7717ae8', 3, 'The Pod''s resources.limits.memory being set too low');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8fc0ad72-8cfb-4802-bd9c-38deb4523736', 'e4239271-032a-48b9-9e87-893183951445', 0, 'ErrImagePull is the immediate failed pull attempt; ImagePullBackOff is the kubelet backing off with increasing delay between repeated retries after ErrImagePull recurs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14adabe5-3b73-4eb1-a3be-55df81e5ec78', 'e4239271-032a-48b9-9e87-893183951445', 1, 'They are unrelated failure states from entirely different subsystems');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab2f50f1-acb7-45d6-8019-151951a23f08', 'e4239271-032a-48b9-9e87-893183951445', 2, 'ImagePullBackOff always precedes ErrImagePull, never the other way around');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db832f76-8f7e-4e6c-9d21-aa43cf755053', 'e4239271-032a-48b9-9e87-893183951445', 3, 'ErrImagePull only occurs for public images, ImagePullBackOff only for private ones');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83ec616c-737a-4966-80c8-e19c17eb2b2f', '5dee00f9-89d5-4834-98bc-c498026ce4da', 0, 'kubectl get pod <name> -o yaml (or -o json), to see the complete spec/status as recorded, including fields describe may summarize or omit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce9535ff-5183-4e18-a72d-59e3f8408bba', '5dee00f9-89d5-4834-98bc-c498026ce4da', 1, 'kubectl top pod <name>');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16795bb9-febb-40b5-aa4b-98c50289cfa0', '5dee00f9-89d5-4834-98bc-c498026ce4da', 2, 'kubectl config view');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('abd9235b-265d-440b-8df0-b83d5b5d9552', '5dee00f9-89d5-4834-98bc-c498026ce4da', 3, 'kubectl api-resources');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a24ce8b-ab1f-40ff-8b0f-f8a31a21383d', '0534bfd2-3b23-427e-b55a-a549255c82f2', 0, 'The excess Pods remain Pending, since the hard anti-affinity rule can''t be satisfied once every node already has one matching Pod');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62b9fd22-cfab-4115-beaa-c50ed82e4312', '0534bfd2-3b23-427e-b55a-a549255c82f2', 1, 'Multiple replicas are automatically allowed on the same node once nodes run out');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('00937957-1808-4650-87b3-21bcaa5323a0', '0534bfd2-3b23-427e-b55a-a549255c82f2', 2, 'The anti-affinity rule is silently dropped for the excess Pods');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dddc8d41-0245-4713-87a0-713cb7338837', '0534bfd2-3b23-427e-b55a-a549255c82f2', 3, 'The Deployment controller automatically provisions new nodes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('882bc9a1-0d9b-49cd-a47a-95e740a3ddd5', '35e42cca-ed52-4e75-a60d-10ead582ef10', 0, 'etcdctl endpoint health (and endpoint status), run against the etcd endpoints with the appropriate TLS cert/key/CA flags');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c6e8e60-d58a-4bdf-8fb3-64a583895f4e', '35e42cca-ed52-4e75-a60d-10ead582ef10', 1, 'kubectl get componentstatuses, which fully replaces the need for etcdctl in current Kubernetes versions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fbfa070b-6ef5-473c-b199-a305cd9d9bb7', '35e42cca-ed52-4e75-a60d-10ead582ef10', 2, 'kubectl describe node, which reports etcd latency directly');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4655ae85-d2f8-4118-b186-4b7a5d954bd9', '35e42cca-ed52-4e75-a60d-10ead582ef10', 3, 'kubectl logs etcd -n default');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ea7d11a-b8ed-477c-9cc0-bb8413f92b1d', 'ae137dbf-e783-4865-a338-4e0fcf0fb516', 0, 'Whether the CoreDNS Pods (in kube-system) are actually Running/Ready, and check their logs for errors — a CoreDNS outage breaks cluster-wide DNS for every Pod');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fcb872ab-7855-498f-ab64-b9a37d751990', 'ae137dbf-e783-4865-a338-4e0fcf0fb516', 1, 'Whether the Pod''s own securityContext.runAsUser is set correctly');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a5fc1e7-4288-4c66-b4e5-7f638861752c', 'ae137dbf-e783-4865-a338-4e0fcf0fb516', 2, 'Whether the PersistentVolume backing the Pod is Bound');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9582a31f-21ac-41c4-b537-e99270912a30', 'ae137dbf-e783-4865-a338-4e0fcf0fb516', 3, 'Whether the Deployment''s revisionHistoryLimit is set too low');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8565791d-32a1-4d45-aed5-9130d7e52235', '24839362-94bd-4d97-bef9-4e6d08f8dc70', 0, 'Confirm the target Pods are actually Ready (failing readinessProbe Pods are excluded from Endpoints even if labels match), and check that kube-proxy is running correctly on the relevant nodes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8105c8a4-6539-42e1-b64c-d1a37904c9c3', '24839362-94bd-4d97-bef9-4e6d08f8dc70', 1, 'Delete and recreate the Namespace');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('95c71bcc-f3a5-46dd-80ab-c254c212dbaa', '24839362-94bd-4d97-bef9-4e6d08f8dc70', 2, 'Increase the Service''s port number');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('316a3920-3a68-42be-b9cd-2d8ee8a76bdc', '24839362-94bd-4d97-bef9-4e6d08f8dc70', 3, 'Switch the Service''s type from ClusterIP to Headless, which always fixes routing issues');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('352ddb1d-ff4f-4eb5-b904-8025b26cd4cf', '3fffe203-3598-4dc8-8256-27a88cdbdabe', 0, 'journalctl -u kubelet');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76250f27-1721-4ab4-9aa3-471eb050cc96', '3fffe203-3598-4dc8-8256-27a88cdbdabe', 1, 'kubectl logs kubelet -n kube-system');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d07a8615-c8ba-45ff-b585-40286b8951a3', '3fffe203-3598-4dc8-8256-27a88cdbdabe', 2, 'crictl logs kubelet');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fbe73e0d-aee3-4b0b-87e4-ba1fecd3bb76', '3fffe203-3598-4dc8-8256-27a88cdbdabe', 3, 'kubectl describe node --logs');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7e473e7a-e499-49d1-a18f-3de213650552', 'b241752e-931d-459a-82d7-fb17055c03c9', 0, 'It talks directly to the node''s container runtime (via the CRI) to inspect/debug containers, images, and pods at a level below what kubectl exposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d8131ba-6213-4423-a38f-52e7c9e8b80e', 'b241752e-931d-459a-82d7-fb17055c03c9', 1, 'It''s a kubectl plugin for cross-cluster comparison');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a6531a5-cbd2-43ca-b7f5-039c4a4f7e3e', 'b241752e-931d-459a-82d7-fb17055c03c9', 2, 'It replaces kubeadm for cluster bootstrapping');
